START = "\x02"
STOP = "\x03"


def train(sequences, order):
    if order < 1:
        raise ValueError("order must be at least 1")
    if not sequences:
        raise ValueError("no training sequences")
    counts = {}
    for sequence in sequences:
        padded = [START] * order + list(sequence) + [STOP]
        for i in range(len(padded) - order):
            context = tuple(padded[i:i + order])
            nxt = padded[i + order]
            counts.setdefault(context, {})
            counts[context][nxt] = counts[context].get(nxt, 0) + 1
    table = {}
    for context, row in counts.items():
        total = sum(row.values())
        table[context] = {token: n / total for token, n in sorted(row.items())}
    return table


def walk(table, order, pick, max_length=100):
    context = (START,) * order
    out = []
    while len(out) < max_length:
        row = table.get(context)
        while row is None and len(context) > 1:
            context = context[1:]
            padded = (START,) * (order - len(context)) + context
            row = table.get(padded)
            if row is not None:
                context = padded
        if row is None:
            raise KeyError(f"no row for context {context!r}")
        token = pick(row)
        if token not in row:
            raise ValueError(f"{token!r} is not a possible next token")
        if token == STOP:
            break
        out.append(token)
        context = tuple((list(context) + [token])[-order:])
    return "".join(out)
